"""
搜索结果面板 - 现代化简约设计
"""

from PyQt6.QtWidgets import (
    QWidget, QVBoxLayout, QHBoxLayout, QLabel, QFrame,
    QScrollArea, QPushButton
)
from PyQt6.QtCore import Qt, pyqtSignal
from PyQt6.QtGui import QFont


class SearchResultsPanel(QWidget):
    """搜索结果面板"""

    result_selected = pyqtSignal(int)  # task_id
    clear_search = pyqtSignal()

    def __init__(self):
        super().__init__()

        self.setFixedWidth(400)
        self.setVisible(False)
        self._init_ui()

    def _init_ui(self):
        """初始化 UI"""
        # 设置现代化样式
        self.setStyleSheet("""
            QWidget#searchResultsPanel {
                background-color: white;
                border: 1px solid #e0e0e0;
                border-radius: 12px;
            }
        """)
        self.setObjectName("searchResultsPanel")

        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        # 标题栏
        header_layout = QHBoxLayout()
        header_layout.setContentsMargins(16, 12, 16, 12)

        self.title_label = QLabel("🔍 Search Results")
        self.title_label.setFont(QFont("Arial", 13, QFont.Weight.Bold))
        self.title_label.setStyleSheet("color: #333333;")
        header_layout.addWidget(self.title_label)

        header_layout.addStretch()

        # 清除按钮
        self.clear_btn = QPushButton("✕")
        self.clear_btn.setFixedSize(28, 28)
        self.clear_btn.setToolTip("Close search results")
        self.clear_btn.setStyleSheet("""
            QPushButton {
                border: none;
                border-radius: 14px;
                background-color: #f5f5f5;
                color: #666666;
                font-size: 14px;
                font-weight: bold;
            }
            QPushButton:hover {
                background-color: #e0e0e0;
                color: #333333;
            }
            QPushButton:pressed {
                background-color: #d0d0d0;
            }
        """)
        self.clear_btn.clicked.connect(self.clear_search.emit)
        header_layout.addWidget(self.clear_btn)

        layout.addLayout(header_layout)

        # 分隔线
        separator = QFrame()
        separator.setFrameShape(QFrame.Shape.HLine)
        separator.setStyleSheet("background-color: #e8e8e8; max-height: 1px;")
        layout.addWidget(separator)

        # 滚动区域
        self.scroll_area = QScrollArea()
        self.scroll_area.setWidgetResizable(True)
        self.scroll_area.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll_area.setStyleSheet("""
            QScrollArea {
                border: none;
                background-color: white;
            }
            QScrollBar:vertical {
                background-color: #f5f5f5;
                width: 8px;
                border-radius: 4px;
                margin: 0;
            }
            QScrollBar::handle:vertical {
                background-color: #bdbdbd;
                border-radius: 4px;
                min-height: 20px;
            }
            QScrollBar::handle:vertical:hover {
                background-color: #9e9e9e;
            }
        """)

        # 内容容器
        self.content_widget = QWidget()
        self.content_layout = QVBoxLayout(self.content_widget)
        self.content_layout.setContentsMargins(16, 16, 16, 16)
        self.content_layout.setSpacing(12)
        self.content_layout.addStretch()

        self.scroll_area.setWidget(self.content_widget)
        layout.addWidget(self.scroll_area)

        # 空状态提示
        self.empty_label = QLabel("No results found")
        self.empty_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.empty_label.setStyleSheet("""
            color: #999999;
            font-size: 14px;
            padding: 40px;
        """)
        self.empty_label.setVisible(False)

    def show_results(self, tasks, keyword: str = ""):
        """显示搜索结果"""
        # 清空现有内容
        self._clear_content()

        if not tasks:
            self.empty_label.setVisible(True)
            self.title_label.setText(f"🔍 Search Results (0)")
        else:
            self.empty_label.setVisible(False)
            self.title_label.setText(f"🔍 Search Results ({len(tasks)})")

            # 添加搜索结果项
            for task in tasks:
                self._add_result_item(task)

        self.setVisible(True)

    def _add_result_item(self, task):
        """添加搜索结果项"""
        item_widget = QWidget()
        item_widget.setStyleSheet("""
            QWidget {
                background-color: white;
                border: 1px solid #e8e8e8;
                border-radius: 8px;
            }
            QWidget:hover {
                background-color: #f5f9ff;
                border: 1px solid #2196F3;
            }
        """)

        layout = QVBoxLayout(item_widget)
        layout.setContentsMargins(12, 12, 12, 12)
        layout.setSpacing(6)

        # 标题行
        title_layout = QHBoxLayout()
        title_layout.setSpacing(8)

        # 优先级标记
        priority_dot = QLabel("●")
        priority_colors = {3: "#EF4444", 2: "#F59E0B", 1: "#10B981"}
        priority_text = {3: "P0", 2: "P1", 1: "P2"}
        priority_dot.setStyleSheet(f"""
            color: {priority_colors.get(task.priority, '#10B981')};
            font-size: 16px;
            font-weight: bold;
        """)
        title_layout.addWidget(priority_dot)

        # 任务标题
        title_label = QLabel(task.title)
        title_label.setFont(QFont("Arial", 13, QFont.Weight.Medium))
        title_label.setStyleSheet("color: #333333;")
        title_label.setWordWrap(True)
        title_layout.addWidget(title_label, stretch=1)

        layout.addLayout(title_layout)

        # 描述 (如果有)
        if task.description:
            desc_label = QLabel(task.description[:80] + ("..." if len(task.description) > 80 else ""))
            desc_label.setStyleSheet("""
                color: #666666;
                font-size: 12px;
            """)
            desc_label.setWordWrap(True)
            layout.addWidget(desc_label)

        # 元信息行
        meta_layout = QHBoxLayout()
        meta_layout.setSpacing(12)

        # 日期
        date_label = QLabel(f"📅 {task.due_date.strftime('%Y-%m-%d')}")
        date_label.setStyleSheet("""
            color: #999999;
            font-size: 11px;
        """)
        meta_layout.addWidget(date_label)

        # 状态
        status_colors = {0: "#F59E0B", 1: "#3B82F6", 2: "#10B981"}
        status_text = {0: "Pending", 1: "In Progress", 2: "Completed"}
        status_label = QLabel(f"● {status_text.get(task.status, 'Pending')}")
        status_label.setStyleSheet(f"""
            color: {status_colors.get(task.status, '#F59E0B')};
            font-size: 11px;
            font-weight: 500;
        """)
        meta_layout.addWidget(status_label)

        # 分类 (如果有)
        if task.category:
            category_label = QLabel(f"{task.category.icon} {task.category.name}")
            category_label.setStyleSheet("""
                color: #666666;
                font-size: 11px;
            """)
            meta_layout.addWidget(category_label)

        meta_layout.addStretch()
        layout.addLayout(meta_layout)

        # 添加到布局
        self.content_layout.insertWidget(self.content_layout.count() - 1, item_widget)

        # 点击事件
        from PyQt6.QtWidgets import QGraphicsOpacityEffect
        from PyQt6.QtCore import QPropertyAnimation

        item_widget.mousePressEvent = lambda e: self._on_item_clicked(task.id)
        item_widget.setCursor(Qt.CursorShape.PointingHandCursor)

    def _on_item_clicked(self, task_id: int):
        """点击结果项"""
        self.result_selected.emit(task_id)
        self.setVisible(False)

    def _clear_content(self):
        """清空内容"""
        while self.content_layout.count() > 1:  # 保留最后的 stretch
            item = self.content_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

        self.empty_label.setVisible(False)

/* Todo Calendar - 现代简约风格样式表 v3.0 */
/* 设计理念：少即是多，留白、圆角、层次分明 */

/* ========== 主题色 ========== */
/* 主色：#3B82F6 (蓝色) */
/* 成功：#10B981 (绿色) */
/* 警告：#F59E0B (黄色) */
/* 错误：#EF4444 (红色) */
/* 背景：#F9FAFB (浅灰) */
/* 卡片：#FFFFFF (白色) */
/* 边框：#E5E7EB (淡灰) */
/* 文字：#1F2937 (深灰) */
/* 次要文字：#6B7280 (中灰) */
/* 占位符：#9CA3AF (浅灰) */

/* ========== 主窗口 ========== */
QMainWindow {
    background-color: #F9FAFB;
}

/* ========== 菜单栏 ========== */
QMenuBar {
    background-color: #FFFFFF;
    border-bottom: 1px solid #E5E7EB;
    padding: 8px 16px;
    font-size: 13px;
    color: #1F2937;
}

QMenuBar::item {
    padding: 6px 12px;
    margin: 0 4px;
    border-radius: 6px;
    background-color: transparent;
}

QMenuBar::item:selected {
    background-color: #F3F4F6;
}

QMenuBar::item:pressed {
    background-color: #E5E7EB;
}

/* ========== 菜单 ========== */
QMenu {
    background-color: #FFFFFF;
    border: 1px solid #E5E7EB;
    border-radius: 12px;
    padding: 8px 0;
    font-size: 13px;
    color: #1F2937;
}

QMenu::item {
    padding: 10px 24px;
    margin: 2px 12px;
    border-radius: 6px;
}

QMenu::item:selected {
    background-color: #3B82F6;
    color: #FFFFFF;
}

QMenu::separator {
    height: 1px;
    background: #E5E7EB;
    margin: 6px 16px;
}

/* ========== 状态栏 ========== */
QStatusBar {
    background-color: #FFFFFF;
    border-top: 1px solid #E5E7EB;
    color: #6B7280;
    font-size: 12px;
    padding: 6px 16px;
}

/* ========== 按钮 ========== */
QPushButton {
    background-color: #3B82F6;
    color: #FFFFFF;
    border: none;
    padding: 10px 20px;
    border-radius: 8px;
    font-size: 13px;
    font-weight: 500;
    min-width: 80px;
}

QPushButton:hover {
    background-color: #2563EB;
}

QPushButton:pressed {
    background-color: #1D4ED8;
}

QPushButton:disabled {
    background-color: #D1D5DB;
    color: #9CA3AF;
}

/* 次要按钮 */
QPushButton#secondaryBtn {
    background-color: #FFFFFF;
    color: #3B82F6;
    border: 1px solid #3B82F6;
}

QPushButton#secondaryBtn:hover {
    background-color: #EFF6FF;
}

/* 视图切换按钮 */
QPushButton#viewBtn {
    background-color: transparent;
    color: #6B7280;
    border: 1px solid #E5E7EB;
    padding: 8px 16px;
}

QPushButton#viewBtn:hover {
    background-color: #F3F4F6;
    border-color: #3B82F6;
    color: #3B82F6;
}

QPushButton#viewBtn:checked {
    background-color: #3B82F6;
    border-color: #3B82F6;
    color: #FFFFFF;
}

/* ========== 输入框 ========== */
QLineEdit {
    border: 1px solid #E5E7EB;
    border-radius: 8px;
    padding: 10px 14px;
    background-color: #FFFFFF;
    font-size: 14px;
    color: #1F2937;
    selection-background-color: #3B82F6;
}

QLineEdit:hover {
    border-color: #D1D5DB;
}

QLineEdit:focus {
    border: 2px solid #3B82F6;
    padding: 9px 13px;
}

QLineEdit:disabled {
    background-color: #F3F4F6;
    color: #9CA3AF;
}

QLineEdit::placeholder-text {
    color: #9CA3AF;
}

/* ========== 下拉框 ========== */
QComboBox {
    border: 1px solid #E5E7EB;
    border-radius: 8px;
    padding: 10px 14px;
    background-color: #FFFFFF;
    font-size: 13px;
    color: #1F2937;
    min-width: 120px;
}

QComboBox:hover {
    border-color: #D1D5DB;
}

QComboBox:focus {
    border: 2px solid #3B82F6;
    padding: 9px 13px;
}

QComboBox::drop-down {
    border: none;
    width: 30px;
}

QComboBox::down-arrow {
    image: none;
    border-left: 5px solid transparent;
    border-right: 5px solid transparent;
    border-top: 5px solid #6B7280;
    margin-right: 12px;
}

QComboBox QAbstractItemView {
    border: 1px solid #E5E7EB;
    border-radius: 8px;
    background-color: #FFFFFF;
    selection-background-color: #3B82F6;
    outline: none;
    padding: 8px 0;
}

QComboBox QAbstractItemView::item {
    padding: 10px 20px;
    margin: 2px 8px;
    border-radius: 6px;
}

/* ========== 日历表格 ========== */
QTableWidget {
    border: 1px solid #E5E7EB;
    border-radius: 12px;
    background-color: #FFFFFF;
    gridline-color: #F3F4F6;
    font-size: 13px;
    selection-background-color: #DBEAFE;
}

QTableWidget::item {
    padding: 8px;
    border: 1px solid #F9FAFB;
    border-radius: 8px;
    margin: 2px;
}

QTableWidget::item:selected {
    background-color: #DBEAFE;
    border: 2px solid #3B82F6;
