QTableWidget::item:hover {
    background-color: #F3F4F6;
}

QTableWidget::corner {
    background-color: #F9FAFB;
    border: none;
}

QHeaderView::section {
    background-color: #F9FAFB;
    color: #6B7280;
    font-weight: 600;
    padding: 10px;
    border: none;
    border-bottom: 2px solid #E5E7EB;
    border-radius: 0;
    text-transform: uppercase;
    font-size: 11px;
    letter-spacing: 0.5px;
}

/* ========== 滚动条 ========== */
QScrollBar:vertical {
    background-color: #F3F4F6;
    width: 8px;
    border-radius: 4px;
    margin: 0;
}

QScrollBar::handle:vertical {
    background-color: #D1D5DB;
    border-radius: 4px;
    min-height: 20px;
